def solve_n_queens(n, fixed):
    """Solve N-Queens with fixed assignments."""
    def is_valid(queens, row, col):
        for r in range(row):
            c = queens[r]
            if c == col:  # Same column
                return False
            if abs(r - row) == abs(c - col):  # Same diagonal
                return False
        return True

    def backtrack(row, queens):
        if row == n:
            return queens[:]

        if row in fixed:
            col = fixed[row]
            if is_valid(queens, row, col):
                queens.append(col)
                result = backtrack(row + 1, queens)
                if result:
                    return result
                queens.pop()
            return None

        for col in range(n):
            if col in queens:  # Column already used
                continue
            if is_valid(queens, row, col):
                queens.append(col)
                result = backtrack(row + 1, queens)
                if result:
                    return result
                queens.pop()
        return None

    return backtrack(0, [])

